DL = json.load(open(os.path.join(ROOT, "esm/results/datalake/results.json"), encoding="utf-8"))


def _lake_pareto(ax, t, ttls, offs, title):
    """served-wrong % vs LLM tokens per fact (thousands, log); NEVER (0 tokens) drawn at the left edge."""
    def xv(k):
        return max(t[k]["tok_per_fact"] / 1000.0, 7.0)

    for k, col, fmt, ms in [("NEVER", OI["blue"], "o", 4), ("ESM-norepair", OI["red"], "*", 8)]:
        r = t[k]
        lo, hi = r["sw_ci"]
        ax.errorbar(xv(k), 100 * r["sw"], yerr=[[100 * (r["sw"] - lo)], [100 * (hi - r["sw"])]],
                    fmt=fmt, ms=ms, color=col, ecolor=col, elinewidth=0.6, capsize=1.5)
    refs = [f"{x}@oracle" for x in ttls] + ["FILEHASH@oracle", "REPLAY@oracle"]
    for k in refs:
        ax.plot(xv(k), 100 * t[k]["sw"], "s", ms=3.5, mfc="none", mec=OI["grey"], mew=0.8)
    names = {"NEVER": "NEVER", "ESM-norepair": "ESM", "REPLAY@oracle": "REPLAY/MANIFEST\n@oracle"}
    for k, (dx, dy) in offs.items():
        ha = "left" if dx > 0 else ("right" if dx < 0 else "center")
        isref = "@oracle" in k
        lab = names.get(k, k)
        if isref and dx <= 0 and "\n" not in lab:  # labels left of / below a marker: two lines to stay narrow
            lab = lab.replace("@oracle", "\n@oracle")
        ax.annotate(lab, (xv(k), 100 * t[k]["sw"]), xytext=(dx, dy), textcoords="offset points",
                    fontsize=5.0 if isref else 5.8, ha=ha, va="center",
                    color="#666666" if isref else (OI["red"] if k.startswith("ESM") else "black"))
    ax.set_xscale("log")
    ax.set_xlim(5, 12000)
    ax.set_xticks([7, 100, 1000, 10000])
    ax.set_xticklabels(["0", "100", "1k", "10k"])
    ax.minorticks_off()
    ax.set_xlabel("LLM tokens per fact (thousands, log)", fontsize=6.2)
    ax.grid(True, which="major", lw=0.3, alpha=0.5)
    ax.set_title(title, loc="left", fontsize=6.8)


