# ---------------------------------------------------------------- ESWA B3: end-to-end tasks (code + lakes)
# Sources: esm/results/e2e/results.json (generated by esm.e2e.report_e2e) and esm/results/e2e_lake/results.json
# (generated by esm.e2e_lake.report_lake): keys arms[...] (main prompt) and trust[...] ("rely on memory" prompt; the
# NO-MEMORY row of the trust variant is the main run). wrong = [point, lo, hi] (bootstrap over tasks), tok = tokens/task.
def _clust_wrong(d, variant, arm, nb=2000, seed=1):
    """Wrong-action rate with a fact-clustered 95 % bootstrap interval (ESWA round 1: tasks of one fact are not
    independent). Reads the task_outcomes parquet next to the results.json the figure was given."""
    import numpy as np, pandas as pd
    base = os.path.join(ROOT, "esm/results/e2e" if d.get("_kind") == "code" else "esm/results/e2e_lake")
    m = pd.read_parquet(os.path.join(base, "task_outcomes.parquet"))
    df = m if (variant == "main" or arm == "NO-MEMORY") else pd.read_parquet(os.path.join(base, "task_outcomes_trust.parquet"))
    s = df[df.arm == arm]
    if s.empty:
        return None
    x = (s.outcome == "wrong").astype(float).to_numpy()
    g = pd.Series(x).groupby(s.iid.to_numpy())
    S, N = g.sum().to_numpy(), g.size().to_numpy()
    idx = np.random.default_rng(seed).integers(0, len(S), (nb, len(S)))
    lo, hi = np.percentile(S[idx].sum(1) / N[idx].sum(1), [2.5, 97.5])
    return (x.mean(), lo, hi)


def fig_e2e():
    e2e = json.load(open(os.path.join(ROOT, "esm/results/e2e/results.json"), encoding="utf-8"))
    lake = json.load(open(os.path.join(ROOT, "esm/results/e2e_lake/results.json"), encoding="utf-8"))
    e2e["_kind"], lake["_kind"] = "code", "lake"
    fig, axs = plt.subplots(1, 2, figsize=(COL, 2.15))
    specs = [(axs[0], e2e, "TTL100", "(a) Code repositories, 120 tasks", (0, 30), (-0.5, 20)),
             (axs[1], lake, "TTL", "(b) Data lakes, 63 tasks", (0, 85), (-1, 56))]
    style = {"NO-MEMORY": (OI["black"], "o"), "NEVER": (OI["blue"], "o"), "TTL": (OI["green"], "^"),
             "REPLAY": (OI["purple"], "v"), "ESM": (OI["red"], "*"), "ORACLE": (OI["grey"], "s")}
    for ax, d, ttl, title, xl, yl in specs:
        for arm in ["NO-MEMORY", "NEVER", ttl, "REPLAY", "ESM", "ORACLE"]:
            key = "TTL" if arm == ttl else arm
            col, mk = style[key]
            ms = 6.5 if key == "ESM" else 3.6
            m = d["arms"][arm]
            t = d["trust"].get(arm, m) if arm != "NO-MEMORY" else m  # NO-MEMORY has no memory to rely on
            for r, filled, cl in [(m, True, _clust_wrong(d, "main", arm)), (t, False, _clust_wrong(d, "trust", arm))]:
                w, lo, hi = (100 * v for v in (cl if cl is not None else r["wrong"]))
                ax.errorbar(r["tok"] / 1000, w, yerr=[[w - lo], [hi - w]], fmt=mk, ms=ms, color=col, ecolor=col,
                            mfc=col if filled else "white", mec=col, mew=0.7, elinewidth=0.45, capsize=1.0,
                            alpha=1.0 if filled else 0.85, zorder=3 if filled else 2)
            if arm != "NO-MEMORY":
                ax.annotate("", (t["tok"] / 1000, 100 * t["wrong"][0]), (m["tok"] / 1000, 100 * m["wrong"][0]),
                            arrowprops=dict(arrowstyle="->", lw=0.4, color=col, alpha=0.7, shrinkA=2, shrinkB=2))
        ax.axhline(100 * d["arms"]["NO-MEMORY"]["wrong"][0], ls=":", lw=0.6, color=OI["black"], zorder=1)
        ax.set_xlim(*xl)
        ax.set_ylim(*yl)
        ax.set_title(title, loc="left", fontsize=5.9)
        ax.set_xlabel("tokens per task (thousands)", fontsize=6.0)
        ax.grid(True, lw=0.3, alpha=0.5)
    axs[0].set_ylabel("wrong actions (% of tasks)", fontsize=6.2)
    from matplotlib.lines import Line2D
    hs = [Line2D([], [], ls="", marker=style[k][1], color=style[k][0], ms=6 if k == "ESM" else 3.5, label=k)
          for k in ["NO-MEMORY", "NEVER", "TTL", "REPLAY", "ESM", "ORACLE"]]
    hs += [Line2D([], [], ls="", marker="o", color="#555555", ms=3.5, label="main prompt"),
           Line2D([], [], ls="", marker="o", mfc="white", mec="#555555", ms=3.5, label='"rely on memory"')]
    fig.legend(handles=hs, loc="upper center", ncol=4, frameon=False, fontsize=5.3, bbox_to_anchor=(0.53, 1.13),
               handletextpad=0.2, columnspacing=0.8)
    fig.tight_layout(w_pad=0.8)
    save(fig, "fig_e2e.pdf")


